// Match Gorgias users with Slack users by email
const gorgiasUsers = $input.first().json.data || [];
const slackUsers = $input.last().json.members || [];

const parsed = [];

console.log('═══════════════════════════════════════');
console.log('👥 Matching Gorgias Users with Slack');
console.log(`   Gorgias users: ${gorgiasUsers.length}`);
console.log(`   Slack users: ${slackUsers.length}`);
console.log('═══════════════════════════════════════');

// Create Slack email lookup map
const slackByEmail = {};
for (const slackUser of slackUsers) {
  if (slackUser.profile?.email && !slackUser.deleted && !slackUser.is_bot) {
    slackByEmail[slackUser.profile.email.toLowerCase()] = slackUser;
  }
}

// Match Gorgias users
for (const gorgiasUser of gorgiasUsers) {
  const email = (gorgiasUser.email || '').toLowerCase();
  const slackUser = slackByEmail[email];

  // Determine role from Gorgias
  let role = 'agent';
  if (gorgiasUser.role === 'admin') {
    role = 'admin';
  } else if (gorgiasUser.role === 'owner') {
    role = 'owner';
  }

  const userData = {
    gorgias_user_id: gorgiasUser.id,
    email: email,
    full_name: gorgiasUser.name || gorgiasUser.firstname + ' ' + gorgiasUser.lastname || email.split('@')[0],
    first_name: gorgiasUser.firstname || '',
    last_name: gorgiasUser.lastname || '',
    role: role,
    is_active: gorgiasUser.active !== false,
    is_bot: false,
    updated_at: new Date().toISOString()
  };

  // Add Slack data if matched
  if (slackUser) {
    userData.slack_user_id = slackUser.id;
    userData.slack_display_name = slackUser.profile?.display_name || slackUser.real_name || userData.full_name;
    userData.slack_real_name = slackUser.real_name || userData.full_name;
    userData.slack_avatar_url = slackUser.profile?.image_192 || null;

    console.log(`✅ Matched: ${userData.full_name} (${email})`);
  } else {
    userData.slack_user_id = null;
    userData.slack_display_name = null;
    userData.slack_real_name = null;
    userData.slack_avatar_url = null;

    console.log(`⚠️  No Slack match: ${userData.full_name} (${email})`);
  }

  parsed.push({
    json: userData
  });
}

console.log('───────────────────────────────────────');
console.log(`✅ Processed ${parsed.length} users`);
const matchedCount = parsed.filter(p => p.json.slack_user_id).length;
console.log(`   Matched with Slack: ${matchedCount}`);
console.log(`   No Slack match: ${parsed.length - matchedCount}`);
console.log('═══════════════════════════════════════');

return parsed;

// Calculate sync statistics
const items = $input.all();

const matchedCount = items.filter(i => i.json.slack_user_id).length;
const unmatchedCount = items.length - matchedCount;

const stats = {
  total_processed: items.length,
  matched_with_slack: matchedCount,
  unmatched: unmatchedCount,
  sync_timestamp: new Date().toISOString(),
  workflow: 'gorgias_users_sync',
  status: 'success'
};

console.log('═══════════════════════════════════════');
console.log('✅ Users Sync Complete');
console.log(`   Total users synced: ${stats.total_processed}`);
console.log(`   Matched with Slack: ${stats.matched_with_slack}`);
console.log(`   Unmatched: ${stats.unmatched}`);
console.log(`   Timestamp: ${stats.sync_timestamp}`);
console.log('═══════════════════════════════════════');

return [{ json: stats }];

